	public void onEvent(Event e) {

		if (e instanceof EventSneaking) {

			if (e.isPre()) {

				if (SpicyClient.config.killaura.isEnabled() && SpicyClient.config.killaura.target != null) {
					return;
				}

				EventSneaking sneak = (EventSneaking) e;

